6: import { ImageGenerationWorkbench } from '@/components/ImageGenerationWorkbench';
7: import { ReversePromptForm } from '@/components/ReversePromptForm';
8: import { GifGenerationWorkspace } from '@/components/GifGenerationWorkspace';
9: import { AgentChatWorkspace } from '@/components/agent/AgentChatWorkspace';
10: import { AssetsWorkspace } from '@/components/assets/AssetsWorkspace';
11: import { CanvasWorkspace } from '@/components/canvas/CanvasWorkspace';
12: import type { CanvasTaskImportRequest } from '@/components/canvas/canvas-job-import';
13: import { PromptGallery, type PromptGalleryRestorePosition } from '@/components/PromptGallery';
14: import type { PromptWithKey } from '@/lib/prompt-gallery-data';
15: import { SettingsModal } from '@/components/SettingsModal';
16: import { MissingApiKeyDialog } from '@/components/MissingApiKeyDialog';
17: import { useQueueStatus } from '@/hooks/useQueueStatus';
18: import { useWideMode } from '@/hooks/useWideMode';
19: import { useServerTaskPolling } from '@/hooks/useServerTaskPolling';
20: import { useWorkspaceJobs } from '@/hooks/useWorkspaceJobs';
21: import { QueueStatusSummary, WorkspaceHeader, type WorkspaceHeaderRef } from '@/components/workspace/WorkspaceHeader';
22: import { WorkspaceModeTabs } from '@/components/workspace/WorkspaceModeTabs';
23: import { ActiveJobList, HistoryJobList, isWaitingJob, type GenerationHistoryFilter, type HistoryClearScope } from '@/components/workspace/results/HistoryJobList';
24: import { PromptGalleryAccessDialog, usePromptGalleryAccess } from '@/components/workspace/PromptGalleryAccess';
25: import { usePromptGalleryConfig } from '@/hooks/usePromptGalleryConfig';
26: import { ConfirmDialog } from '@/components/workspace/dialogs/ConfirmDialog';
27: import { Toast, type ToastData } from '@/components/workspace/Toast';
28: import { Button, buttonVariants } from '@/components/ui/button';
29: import { ThemeToggle } from '@/components/ThemeToggle';
30: import {
31:   DropdownMenu,
32:   DropdownMenuContent,
33:   DropdownMenuItem,
34:   DropdownMenuTrigger,
35: } from '@/components/ui/dropdown-menu';
36: import { Shuffle, Settings, User, Wallpaper, PanelLeftClose, PanelLeftOpen } from 'lucide-react';
37: import { getNovaTask } from '@/lib/ccode-task-client';
38: import { finalizeCompletedServerTask } from '@/lib/workspace-task-service';
39: import { classifyTaskFailure } from '@/lib/task-failure';
40: import type { RefImageData, StoredJob } from '@/lib/job-store';
41: import { subscribeImageActionToasts, subscribeUseAsImageReference } from '@/lib/image-actions';
42: import {
43:   submitImageToImage,
44:   submitTextToImage,
45:   type SubmitActions,
46: } from '@/lib/workspace-task-service';
47: import { cn } from '@/lib/utils';
48: import { BA_RANDOM_URL, BING_WALLPAPER_URL } from '@/lib/constants';
49: import { isDesktopRuntime } from '@/lib/desktop-bridge';
50: 
51: export function WorkspaceShell() {
52:   const queueStatus = useQueueStatus();
53:   const { wideMode, mounted, toggleWideMode } = useWideMode();
54:   const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
55:   const desktopRuntime = mounted && isDesktopRuntime();
56:   const [settingsOpen, setSettingsOpen] = useState(false);
57:   const [missingApiKeyDialogOpen, setMissingApiKeyDialogOpen] = useState(false);
58:   const [error, setError] = useState<string | null>(null);
59:   const [activeTab, setActiveTab] = useState<'image-generation' | 'agent' | 'canvas' | 'assets' | 'reverse-prompt' | 'gif' | 'prompt-gallery'>('agent');
60:   const [generationHistoryFilter, setGenerationHistoryFilter] = useState<GenerationHistoryFilter>('all');
61:   const [generationClearScope, setGenerationClearScope] = useState<HistoryClearScope | null>(null);
62:   const [referenceDraft, setReferenceDraft] = useState<{ id: number; refImages: RefImageData[]; prompt?: string } | null>(null);
63:   const [canvasTaskImport, setCanvasTaskImport] = useState<CanvasTaskImportRequest | null>(null);
64:   const [canvasPromptGalleryImport, setCanvasPromptGalleryImport] = useState<PromptWithKey | null>(null);
65:   const [canvasReturnToPromptGallery, setCanvasReturnToPromptGallery] = useState(false);
66:   const [promptGalleryRestorePosition, setPromptGalleryRestorePosition] = useState<PromptGalleryRestorePosition | null>(null);
67:   const workspace = useWorkspaceJobs();
68:   const galleryConfig = usePromptGalleryConfig();
69:   const promptGallery = usePromptGalleryAccess(galleryConfig.mode, galleryConfig.passwordEnabled, setError, () => setActiveTab('prompt-gallery'));
70: 
71:   // Toast state
72:   const [toasts, setToasts] = useState<ToastData[]>([]);
73:   const toastIdRef = useRef(0);
74:   const headerRef = useRef<WorkspaceHeaderRef>(null);
75:   const referenceDraftIdRef = useRef(0);
76:   const promptGalleryScrollPositionRef = useRef<Omit<PromptGalleryRestorePosition, 'key'>>({ windowY: 0, workspaceY: 0 });
77:   const promptGalleryRestoreKeyRef = useRef(0);
78: 
79:   const showToast = useCallback((message: string, type: ToastData['type']) => {
80:     const id = `toast-${++toastIdRef.current}`;
81:     setToasts(prev => [...prev, { id, message, type }]);
82:   }, []);
83:   const dismissToast = useCallback((id: string) => {
84:     setToasts(prev => prev.filter(t => t.id !== id));
85:   }, []);
86: 
87:   useEffect(() => subscribeImageActionToasts(detail => showToast(detail.message, detail.type)), [showToast]);
88: 
89:   useEffect(() => subscribeUseAsImageReference(detail => {
90:     workspace.setRetryData(null);
91:     setReferenceDraft({ id: ++referenceDraftIdRef.current, refImages: detail.refImages, prompt: detail.prompt });
92:     setActiveTab('image-generation');
93:   }), [workspace]);
94: 
95:   const handleImageDraftConsumed = useCallback(() => {
96:     workspace.setRetryData(null);
97:     setReferenceDraft(null);
98:   }, [workspace]);
99: 
100:   const handleTaskImportToCanvas = useCallback((request: CanvasTaskImportRequest) => {
101:     setCanvasTaskImport(request);
102:     setActiveTab('canvas');
103:   }, []);
104: 
105:   const handlePromptGalleryImportToCanvas = useCallback((prompt: PromptWithKey, position: Omit<PromptGalleryRestorePosition, 'key'>) => {
106:     promptGalleryScrollPositionRef.current = position;
107:     setCanvasPromptGalleryImport(prompt);
108:     setCanvasReturnToPromptGallery(true);
109:     setActiveTab('canvas');
110:   }, []);
111: 
112:   const handleReturnToPromptGallery = useCallback(() => {
113:     setActiveTab('prompt-gallery');
114:     setCanvasReturnToPromptGallery(false);
115:     setPromptGalleryRestorePosition({
116:       key: ++promptGalleryRestoreKeyRef.current,
117:       ...promptGalleryScrollPositionRef.current,
118:     });
119:   }, []);
120: 
121:   // Checking debounce state
122:   const [checkingJobIds, setCheckingJobIds] = useState<Set<string>>(new Set());
123:   // Cooldown state: jobId -> cooldown end timestamp
124:   const [cooldowns, setCooldowns] = useState<Map<string, number>>(new Map());
125: 
126:   const submitActions = useMemo<SubmitActions>(() => ({
127:     addJob: workspace.addJob,
128:     replaceJob: workspace.replaceJob,
129:     completeJob: workspace.completeJob,
130:     failJob: workspace.failJob,
131:     getJob: workspace.getJob,
132:   }), [workspace.addJob, workspace.completeJob, workspace.failJob, workspace.replaceJob, workspace.getJob]);
133: 
134:   useServerTaskPolling(workspace.jobs, submitActions, workspace.hasJob);
135: 
136:   const handleSubmitError = useCallback((message: string) => {
137:     if (message === '请先配置 API 密钥') {
138:       setError(null);
139:       setMissingApiKeyDialogOpen(true);
140:       return;
141:     }
142:     showToast(message, 'error');
143:   }, [showToast]);
144: 
145:   const handleCheckStatus = useCallback(async (job: StoredJob) => {
146:     if (!job.serverTaskId || checkingJobIds.has(job.id) || cooldowns.has(job.id)) return;
147:     setCheckingJobIds(prev => new Set(prev).add(job.id));
148:     // Set 5s cooldown
149:     setCooldowns(prev => new Map(prev).set(job.id, Date.now() + 5000));
150:     try {
151:       const task = await getNovaTask(job.serverTaskId);
152:       if (task.status === 'completed') {
153:         showToast('生成完成，正在下载图片…', 'success');
154:         await finalizeCompletedServerTask(job, task, submitActions);
155:       } else if (task.status === 'failed' || task.status === 'expired') {
156:         const { terminal } = classifyTaskFailure(task);
157:         const message = task.error || task.warning
158:           || (task.status === 'expired' ? '该任务已超出取回时间' : '任务失败');
159:         void submitActions.failJob(job.id, message, { terminal });
160:         showToast(`任务失败：${message}`, 'error');
161:       } else if (task.status === 'processing') {
162:         submitActions.replaceJob(job.id, cur => ({ ...cur, status: 'processing' }));
163:         showToast('任务正在生成中，请稍候…', 'info');
164:       } else if (task.status === 'queued' || task.status === '排队中') {
165:         submitActions.replaceJob(job.id, cur => ({ ...cur, status: '排队中' }));
166:         showToast('任务排队中，请耐心等待…', 'info');
167:       }
168:     } catch {
169:       showToast('查询失败，请稍后重试', 'error');
170:     } finally {
171:       setCheckingJobIds(prev => { const next = new Set(prev); next.delete(job.id); return next; });
172:       // Cleanup cooldown after 5s
173:       setTimeout(() => {
174:         setCooldowns(prev => {
175:           const next = new Map(prev);
176:           next.delete(job.id);
177:           return next;
178:         });
179:       }, 5000);
180:     }
181:   }, [checkingJobIds, cooldowns, submitActions, showToast]);
182: 
183:   const generationInitialData = useMemo(() => (
184:     workspace.retryData
185:       ? {
186:         prompt: workspace.retryData.prompt,
187:         outputSize: workspace.retryData.outputSize,
188:         customSize: workspace.retryData.customSize,
189:         aspectRatio: workspace.retryData.aspectRatio,
190:         temperature: workspace.retryData.temperature,
191:         model: workspace.retryData.model,
192:         gptImageQuality: workspace.retryData.gptImageQuality,
193:         gptImageStyle: workspace.retryData.gptImageStyle,
194:         gptImageBackground: workspace.retryData.gptImageBackground,
195:         parallelCount: workspace.retryData.parallelCount,
196:         refImages: workspace.retryData.refImages,
197:       }
198:       : undefined
199:   ), [workspace.retryData]);
200: 
201:   const generationJobs = useMemo(
202:     () => [...workspace.textJobs, ...workspace.imageJobs].sort((a, b) => +new Date(b.created_at) - +new Date(a.created_at)),
203:     [workspace.imageJobs, workspace.textJobs]
204:   );
205:   const filteredGenerationJobs = useMemo(
206:     () => generationHistoryFilter === 'all'
207:       ? generationJobs
208:       : generationJobs.filter(job => job.mode === generationHistoryFilter),
209:     [generationHistoryFilter, generationJobs]
210:   );
211:   const generationActiveJobs = useMemo(
212:     () => filteredGenerationJobs.filter(isWaitingJob),
213:     [filteredGenerationJobs]
214:   );
215:   const generationHistoryJobs = useMemo(
216:     () => wideMode ? filteredGenerationJobs.filter(job => !isWaitingJob(job)) : filteredGenerationJobs,
217:     [filteredGenerationJobs, wideMode]
218:   );
219:   const generationEmptyDescription = generationHistoryFilter === 'text-to-image'
220:     ? '提交一段文字描述来生成图片'
221:     : generationHistoryFilter === 'image-to-image'
222:       ? '添加参考图并输入描述来转换'
223:       : '输入提示词，或添加参考图后再生成';
224:   const clearScopeLabel = generationClearScope === 'all'
225:     ? '文生图和图生图'
226:     : generationClearScope === 'text-to-image'
227:       ? '文生图'
228:       : generationClearScope === 'image-to-image'
229:         ? '图生图'
230:         : '当前模式';
231: 
232:   const handleConfirmClearGeneration = useCallback(() => {
233:     if (!generationClearScope) return;
234:     const scope = generationClearScope;
235:     setGenerationClearScope(null);
236:     if (scope === 'all') {
237:       void Promise.all([
238:         workspace.clearJobsByMode('text-to-image'),
239:         workspace.clearJobsByMode('image-to-image'),
240:       ]);
241:       return;
242:     }
243:     if (scope === 'text-to-image' || scope === 'image-to-image') {
244:       void workspace.clearJobsByMode(scope);
245:     }
246:   }, [generationClearScope, workspace]);
247: 
248:   return (
249:     <div
250:       className={cn(
251:         'mx-auto flex min-h-screen w-full flex-col gap-0 overflow-x-hidden px-0 py-0 transition-[max-width] duration-200',
252:         'nova-app-shell',
253:         desktopRuntime && 'nova-desktop-shell',
254:         wideMode
255:           ? 'max-w-none xl:h-dvh xl:min-h-0 xl:overflow-hidden'
256:           : desktopRuntime ? 'max-w-none' : 'max-w-[66rem] sm:px-4 sm:py-4',
257:         !wideMode && activeTab === 'agent' && 'h-dvh min-h-0 overflow-hidden'
258:       )}
259:     >
260:       <div className={cn(
261:         'flex-1 bg-transparent shadow-none sm:rounded-3xl sm:bg-card/95 sm:shadow-sm sm:border sm:border-border/70',
262:         'nova-app-frame',
263:         wideMode && 'nova-app-frame-wide',
264:         desktopRuntime && 'nova-desktop-frame',
265:         wideMode && 'flex min-h-0 flex-col',
266:         !wideMode && activeTab === 'agent' && 'flex min-h-0 flex-col'
267:       )}>
268:         <div className={cn(
269:           'p-0 sm:p-5',
270:           desktopRuntime && 'nova-desktop-inner',
271:           wideMode
272:             ? 'flex h-full flex-1 flex-col min-h-0 sm:p-3'
273:             : activeTab === 'agent'
274:               ? 'flex h-full flex-1 flex-col min-h-0 gap-4'
275:               : 'space-y-4'
276:         )}>
277:           <WorkspaceHeader
278:             ref={headerRef}
279:             queueStatus={queueStatus}
280:             wideMode={wideMode}
281:             onToggleWideMode={toggleWideMode}
282:             onOpenSettings={() => setSettingsOpen(true)}
283:             onLogoClick={promptGallery.handlePromptGalleryEntry}
284:             sidebarMode={wideMode}
285:           />
286: 
287:           <Tabs
288:             value={activeTab}
289:             onValueChange={value => setActiveTab(value as typeof activeTab)}
290:             orientation={wideMode ? 'vertical' : 'horizontal'}
291:             className={cn(
292:               wideMode
293:                 ? cn('gap-4 xl:flex-row xl:flex-1 xl:min-h-0', sidebarCollapsed && 'xl:gap-0')
294:                 : activeTab === 'agent'
295:                   ? 'gap-2 flex flex-col flex-1 min-h-0'
296:                   : 'gap-2'
297:             )}
298:           >
299:             <div className={cn(
300:               'flex flex-col',
301:               wideMode && 'self-stretch sticky top-4 h-full xl:shrink-0',
302:               wideMode && 'nova-app-sidebar',
303:               wideMode && sidebarCollapsed && 'hidden',
304:               desktopRuntime && (wideMode ? 'nova-desktop-sidebar' : 'nova-desktop-topnav'),
305:             )}>
306:               {wideMode && (
307:                 <button
308:                   type="button"
309:                   onClick={promptGallery.handlePromptGalleryEntry}
310:                   className="flex items-center gap-2 px-2 pt-3 pb-1 rounded-xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
311:                   aria-label="AIOSS logo"
312:                 >
313:                   <img
314:                     src="/favicon.png"
315:                     alt="AIOSS"
316:                     className="h-8 w-8 shrink-0 rounded-lg object-cover ring-1 ring-border/60"
317:                   />
318:                   <div className="min-w-0">
319:                     <h2 className="truncate text-base font-semibold tracking-tight leading-tight">AIOSS Image</h2>
320:                     <p className="truncate text-[11px] text-muted-foreground leading-tight">批量 API 图像生成器</p>
321:                   </div>
322:                 </button>
323:               )}
324:               <div className={cn(wideMode ? 'flex flex-col py-4 flex-1' : 'flex flex-col py-1')}>
325:                 <WorkspaceModeTabs wideMode={wideMode} showPromptGallery={promptGallery.showPromptGallery} />
326:               </div>
327: 
328:               {wideMode && (
329:                 <div className="hidden flex-col gap-1 xl:flex">
330:                   <div className="nova-desktop-random flex flex-col gap-1">
331:                     <DropdownMenu modal={false}>
332:                       <DropdownMenuTrigger
333:                         className={cn(buttonVariants({ variant: 'outline', size: 'sm' }), 'w-full justify-start gap-2 rounded-xl px-3 text-xs')}
334:                         title="随机图片"
335:                         aria-label="随机图片"
336:                       >
337:                         <Shuffle className="size-4 shrink-0" />
338:                         随机图片
339:                       </DropdownMenuTrigger>
340:                       <DropdownMenuContent align="start" sideOffset={4}>
341:                         <DropdownMenuItem onClick={() => headerRef.current?.openRandomImage(BA_RANDOM_URL, 'BA人物')}>
342:                           <User className="w-4 h-4" />
343:                           BA人物
344:                         </DropdownMenuItem>
345:                         <DropdownMenuItem onClick={() => headerRef.current?.openRandomImage(BING_WALLPAPER_URL, 'Bing壁纸')}>
346:                           <Wallpaper className="w-4 h-4" />
347:                           Bing壁纸
348:                         </DropdownMenuItem>
349:                       </DropdownMenuContent>
350:                     </DropdownMenu>
351:                   </div>
352: 
353:                   <div className="nova-desktop-sidebar-tools flex flex-col gap-1 [&_button]:w-full [&_button]:justify-start [&_button]:rounded-xl [&_button_svg]:size-4 [&_button_svg]:shrink-0">
354:                     <ThemeToggle />
355:                     <Button
356:                       variant="outline"
357:                       size="sm"
358:                       className="w-full justify-start gap-2 rounded-xl px-3 text-xs"
359:                       onClick={() => setSidebarCollapsed(true)}
360:                       title="隐藏侧栏"
361:                     >
362:                       <PanelLeftClose className="size-4 shrink-0" />
363:                       隐藏侧栏
364:                     </Button>
365:                     <Button variant="outline" size="sm" className="w-full justify-start gap-2 rounded-xl px-3 text-xs" onClick={toggleWideMode}>
366:                       {wideMode ? <PanelLeftClose className="size-4 shrink-0" /> : <PanelLeftOpen className="size-4 shrink-0" />}
367:                       {wideMode ? '退出宽屏' : '宽屏'}
368:                     </Button>
369:                     <Button variant="outline" size="sm" className="w-full justify-start gap-2 rounded-xl px-3 text-xs" onClick={() => setSettingsOpen(true)}>
370:                       <Settings className="size-4 shrink-0" />
371:                       设置
372:                     </Button>
373:                   </div>
374: 
375:                   <div className="nova-desktop-status">
376:                     <QueueStatusSummary queueStatus={queueStatus} compact />
377:                   </div>
378:                 </div>)}
379:             </div>
380: 
381:             <div data-workspace-content-scroll className={cn(
382:               wideMode && 'nova-app-workspace',
383:               wideMode && activeTab === 'image-generation' && 'nova-image-workspace',
384:               wideMode && (activeTab === 'image-generation' || activeTab === 'agent') && 'nova-workspace-bare',
385:               desktopRuntime && 'nova-desktop-workspace',
386:               wideMode && 'xl:relative xl:flex xl:flex-1 xl:min-h-0 xl:min-w-0',
387:               wideMode && sidebarCollapsed && 'xl:pt-10',
388:               wideMode && (activeTab === 'image-generation' || activeTab === 'agent'
389:                 ? 'xl:overflow-hidden'
390:                 : 'xl:overflow-y-auto xl:overflow-x-hidden'),
391:               !wideMode && activeTab === 'agent' && 'flex flex-1 flex-col min-h-0'
392:             )}>
393:               {wideMode && sidebarCollapsed && (
394:                 <Button
395:                   variant="outline"
396:                   size="icon-sm"
397:                   className="absolute left-1 top-1 z-20"
398:                   onClick={() => setSidebarCollapsed(false)}
399:                   title="显示侧栏"
400:                   aria-label="显示侧栏"
401:                 >
402:                   <PanelLeftOpen className="size-4" />
403:                 </Button>
404:               )}
405:               <TabsContent value="image-generation" keepMounted className={cn(wideMode ? 'space-y-6 xl:flex xl:min-h-0 xl:space-y-0' : 'space-y-3')}>
406:                 <div className={cn(wideMode ? 'grid items-start gap-4 xl:h-full xl:min-h-0 xl:flex-1 xl:grid-cols-[clamp(480px,34vw,540px)_minmax(0,1fr)] xl:items-stretch' : 'space-y-3')}>
407:                   {wideMode ? (
408:                     <div className="grid min-h-0 grid-rows-[auto_minmax(0,1fr)] gap-4 xl:h-full xl:overflow-hidden">
409:                       <ActiveJobList
410:                         jobs={generationActiveJobs}
411:                         checkingJobIds={checkingJobIds}
412:                         cooldowns={cooldowns}
413:                         onCancel={jobId => workspace.setCancelJobId(jobId)}
414:                         onCheckStatus={handleCheckStatus}
415:                       />
416:                       <div className="min-h-0 overflow-y-auto pr-1">
417:                         <ImageGenerationWorkbench
418:                           wideMode={wideMode}
419:                           onSubmitText={data => void submitTextToImage(data, submitActions, handleSubmitError)}
420:                           onSubmitImage={data => void submitImageToImage(data, submitActions, handleSubmitError)}
421:                           disabled={!workspace.hasApiKey}
422:                           onConfigureApiKey={() => setSettingsOpen(true)}
423:                           onDraftConsumed={handleImageDraftConsumed}
424:                           initialData={generationInitialData}
425:                           referenceDraft={referenceDraft}
426:                         />
427:                       </div>
428:                     </div>
429:                   ) : (
430:                     <div>
431:                       <ImageGenerationWorkbench
432:                         wideMode={wideMode}
433:                         onSubmitText={data => void submitTextToImage(data, submitActions, handleSubmitError)}
434:                         onSubmitImage={data => void submitImageToImage(data, submitActions, handleSubmitError)}
435:                         disabled={!workspace.hasApiKey}
436:                         onConfigureApiKey={() => setSettingsOpen(true)}
437:                         onDraftConsumed={handleImageDraftConsumed}
438:                         initialData={generationInitialData}
439:                         referenceDraft={referenceDraft}
440:                       />
441:                     </div>
442:                   )}
443:                   <HistoryJobList
444:                     wideMode={wideMode}
445:                     active={activeTab === 'image-generation'}
446:                     title="生图任务"
447:                     mode="text-to-image"
448:                     historyFilter={generationHistoryFilter}
449:                     onHistoryFilterChange={setGenerationHistoryFilter}
450:                     emptyDescription={generationEmptyDescription}
451:                     jobs={generationHistoryJobs}
452:                     loadedImages={workspace.loadedImages}
453:                     checkingJobIds={checkingJobIds}
454:                     cooldowns={cooldowns}
455:                     onRetry={job => {
456:                       workspace.retryJob(job);
