68:   const groups: JobDayGroup[] = [];
69: 
70:   jobs.forEach((job) => {
71:     const date = new Date(job.created_at);
72:     const validDate = !Number.isNaN(date.getTime());
73:     const key = validDate ? getDayKey(date) : 'unknown';
74:     const label = !validDate
75:       ? '较早记录'
76:       : key === todayKey
77:         ? '今天'
78:         : key === yesterdayKey
79:           ? '昨天'
80:           : new Intl.DateTimeFormat('zh-CN', { month: 'long', day: 'numeric', weekday: 'short' }).format(date);
81:     const currentGroup = groups.at(-1);
82:     if (!currentGroup || currentGroup.key !== key) groups.push({ key, label, jobs: [job] });
83:     else currentGroup.jobs.push(job);
84:   });
85: 
86:   return groups;
87: }
