397: function VirtualJobList({
398:   groups,
399:   active,
400:   wideMode,
401:   renderJobCard,
402:   scrollToDayKey,
403:   onScrollToDayComplete,
404:   onVisibleDayChange,
405: }: {
406:   groups: JobDayGroup[];
407:   active: boolean;
408:   wideMode: boolean;
409:   renderJobCard: (job: StoredJob) => React.ReactNode;
410:   scrollToDayKey?: string;
411:   onScrollToDayComplete: () => void;
412:   onVisibleDayChange: (key: string | undefined) => void;
413: }) {
414:   const parentRef = useRef<HTMLDivElement>(null);
415:   const shouldRender = active && groups.length > 0;
416:   const columns = useColumnCount(parentRef, wideMode, shouldRender);
417:   const jobCount = useMemo(() => groups.reduce((total, group) => total + group.jobs.length, 0), [groups]);
418: 
419:   const virtualizer = useVirtualizer({
420:     count: active ? groups.length : 0,
421:     getScrollElement: () => parentRef.current,
422:     estimateSize: () => 420,
423:     overscan: 5,
424:   });
425:   const virtualItems = virtualizer.getVirtualItems();
426:   const visibleDayKey = virtualItems.length > 0 ? groups[virtualItems[0].index]?.key : undefined;
427: 
428:   useEffect(() => {
429:     onVisibleDayChange(visibleDayKey);
430:   }, [onVisibleDayChange, visibleDayKey]);
431: 
432:   useEffect(() => {
433:     if (!scrollToDayKey) return;
434:     const groupIndex = groups.findIndex(group => group.key === scrollToDayKey);
435:     if (groupIndex < 0) return;
436:     virtualizer.scrollToIndex(groupIndex, { align: 'start' });
437:     onScrollToDayComplete();
438:   }, [groups, onScrollToDayComplete, scrollToDayKey, virtualizer]);
439: 
440:   if (!shouldRender) return null;
441: 
442:   return (
443:     <div
444:       ref={parentRef}
445:       className={cn('studio-history-list relative virtual-scroll-container', wideMode && 'studio-history-list-wide min-h-0 flex-1')}
446:       style={{
447:         height: wideMode ? undefined : (jobCount > 3 ? '70vh' : 'auto'),
448:         maxHeight: wideMode ? undefined : '70vh',
449:         minHeight: jobCount > 0 ? '200px' : '0',
450:         overflow: 'auto',
451:         overflowX: 'hidden',
452:       }}
453:     >
454:       <div
455:         style={{
456:           height: `${virtualizer.getTotalSize()}px`,
457:           width: '100%',
458:           position: 'relative',
459:         }}
460:       >
461:         {virtualItems.map(virtualRow => {
462:           const group = groups[virtualRow.index];
463:           return (
464:             <div
465:               key={group.key}
466:               data-index={virtualRow.index}
467:               ref={virtualizer.measureElement}
468:               className="absolute top-0 w-full"
469:               style={{
470:                 transform: `translateY(${virtualRow.start}px)`,
471:               }}
472:             >
473:               <section className="studio-history-day-group pb-4">
474:                 <div className="studio-history-day-divider mb-2.5 flex items-center gap-3">
475:                   <span className="text-xs font-medium text-foreground">{group.label}</span>
476:                   <span className="text-[11px] text-muted-foreground">{group.jobs.length} 项</span>
477:                   <span className="h-px flex-1 bg-border/70" />
478:                 </div>
479:                 <div className="grid gap-3" style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }}>
480:                   {group.jobs.map((job) => (
481:                     <div key={job.id} className="studio-history-job">
482:                       {renderJobCard(job)}
483:                     </div>
484:                   ))}
485:                 </div>
486:               </section>
487:             </div>
488:           );
489:         })}
490:       </div>
491:     </div>
492:   );
493: }
