368: function useColumnCount(
369:   ref: React.RefObject<HTMLDivElement | null>,
370:   wideMode: boolean,
371:   ready: boolean,
372: ) {
373:   const [columns, setColumns] = useState(() => (wideMode && ready ? 3 : 1));
374: 
375:   useEffect(() => {
376:     if (!wideMode || !ready) {
377:       queueMicrotask(() => setColumns(1));
378:       return;
379:     }
380:     const el = ref.current;
