382: 
383:     const compute = () => {
384:       const width = el.clientWidth;
385:       setColumns(getHistoryColumnCount(width));
386:     };
387: 
388:     compute();
389:     const observer = new ResizeObserver(compute);
390:     observer.observe(el);
391:     return () => observer.disconnect();
392:   }, [ref, wideMode, ready]);
393: 
394:   return wideMode ? columns : 1;
395: }
