583:             <div className="flex gap-1">
584:               {allowCheckStatus && (
585:                 <Button variant="ghost" size="icon-sm" onClick={() => onCheckStatus(job)} disabled={checkingJobIds.has(job.id) || (cooldowns.get(job.id) !== undefined && now < cooldowns.get(job.id)!)} title="查看进度">
586:                   {checkingJobIds.has(job.id)
587:                     ? <Loader2 className="w-4 h-4 animate-spin" />
