595:                 <X className="w-4 h-4" />
596:               </Button>
597:             </div>
598:           </div>
599:         </div>
600:       );
601:     }
602:     return null;
603:   };
604: 
605:   return (
606:     <section className={cn(wideMode ? 'nova-studio-history-panel flex h-full min-h-0 flex-col space-y-3 p-4' : 'space-y-3')}>
