637:           renderJobCard={renderJobCard}
638:           scrollToDayKey={effectiveScrollToDayKey}
639:           onScrollToDayComplete={handleScrollToDayComplete}
640:           onVisibleDayChange={handleVisibleDayChange}
641:         />
642:       )}
643:     </section>
644:   );
645: }

