24: function writeStoredWideMode(enabled: boolean): void {
25:   if (typeof window === 'undefined') return;
26: 
27:   try {
28:     const value: StoredWideMode = enabled ? 'enabled' : 'disabled';
29:     runtimeStorage.setItem(WIDE_MODE_STORAGE_KEY, value);
30:   } catch {
31:     // Storage can be unavailable in hardened/private browser modes.
32:   }
