40: function dismissBootLoader(): void {
41:   const el = document.getElementById('app-boot-loader');
42:   if (el) el.remove();
43: }
44: 
45: /** 将宽度模式状态同步到 <html> 属性，确保 CSS 选择器始终有效 */
46: function syncHtmlAttribute(enabled: boolean): void {
47:   if (typeof document === 'undefined') return;
48:   if (enabled) {
49:     document.documentElement.setAttribute('data-wide-mode', '');
50:   } else {
51:     document.documentElement.removeAttribute('data-wide-mode');
52:   }
53: }
