55: export function useWideMode() {
56:   // 初始渲染必须与静态导出 HTML 一致（wideMode=false），否则 wide-mode-init 内联脚本
57:   // 设置的 html[data-wide-mode] 会让客户端首屏读到 true，与构建期 HTML 不符而触发
58:   // React #418 文本水合错误。真实值在挂载后的 effect 中读取；期间由 #app-boot-loader 遮罩覆盖。
