87:     const mql = window.matchMedia(`(max-width: ${WIDE_MODE_MIN_WIDTH - 1}px)`);
88: 
89:     const enforce = (isNarrow: boolean) => {
90:       if (!isNarrow) return;
91:       setWideModeState(current => {
92:         if (!current) return current;
93:         writeStoredWideMode(false);
94:         return false;
95:       });
96:     };
97: 
98:     enforce(mql.matches);
99:     const listener = (event: MediaQueryListEvent) => enforce(event.matches);
100:     mql.addEventListener('change', listener);
