1: import { useEffect, useRef } from 'react';
2: import { novaTaskSocket } from '@/lib/ccode-task-socket';
3: import { finalizeCompletedServerTask, type SubmitActions } from '@/lib/workspace-task-service';
4: import type { StoredJob } from '@/lib/job-store';
5: import { classifyTaskFailure } from '@/lib/task-failure';
6: import type { NovaTaskResponse } from '@/lib/ccode-task-client';
7: 
8: function isWaitingJob(job: StoredJob): boolean {
9:   return job.status === 'processing' || job.status === 'queued' || job.status === '排队中';
10: }
11: 
12: /**
13:  * 用 WebSocket 替代原有的 HTTP 轮询：
14:  * - 每个等待中的 serverTaskId 走 novaTaskSocket.subscribeTask
15:  * - 收到 processing → replaceJob 改状态
16:  * - 收到 completed → finalizeCompletedServerTask
17:  * - 收到 failed/expired → failJob，并根据 classifyTaskFailure 标记 terminal
18:  * - jobs 变化时新增/取消订阅；卸载时全部取消
19:  *
20:  * 不再有 visibilitychange 主动 abort/restart 逻辑（旧版有 race，会重复轮询或卡死）。
21:  * socket 自身负责重连、心跳、HTTP 兜底，详见 nova-task-socket.ts。
22:  */
23: export function useServerTaskPolling(
24:   jobs: StoredJob[],
25:   actions: SubmitActions,
26:   hasJob: (jobId: string) => boolean,
27: ) {
28:   const mountedRef = useRef(false);
29:   const subscriptionsRef = useRef<Map<string, () => void>>(new Map());
30:   const actionsRef = useRef(actions);
31:   const hasJobRef = useRef(hasJob);
32: 
33:   useEffect(() => { actionsRef.current = actions; }, [actions]);
34:   useEffect(() => { hasJobRef.current = hasJob; }, [hasJob]);
35: 
36:   useEffect(() => {
37:     mountedRef.current = true;
38:     const subscriptions = subscriptionsRef.current;
39:     return () => {
40:       mountedRef.current = false;
41:       for (const unsubscribe of subscriptions.values()) {
42:         try { unsubscribe(); } catch { /* ignore */ }
43:       }
44:       subscriptions.clear();
45:     };
46:   }, []);
47: 
48:   useEffect(() => {
49:     const subscriptions = subscriptionsRef.current;
50:     const activeTaskIds = new Set<string>();
51: 
52:     for (const job of jobs) {
53:       if (!isWaitingJob(job) || !job.serverTaskId) continue;
54:       activeTaskIds.add(job.serverTaskId);
55:       if (subscriptions.has(job.serverTaskId)) continue;
56: 
57:       const jobId = job.id;
58:       const taskId = job.serverTaskId;
59:       const handler = (task: NovaTaskResponse) => {
60:         if (!mountedRef.current) return;
61:         if (!hasJobRef.current(jobId)) return;
62:         const actions = actionsRef.current;
63:         // 取最新 job 快照，避免使用订阅时捕获的过期闭包覆盖较新状态。
64:         const currentJob = actions.getJob?.(jobId) ?? job;
65: 
66:         if (task.status === 'completed') {
67:           // 幂等：重连重订阅或 HTTP 兜底可能重复投递 completed；已完成则跳过。
68:           if (currentJob.status === 'completed') return;
69:           // finalizeCompletedServerTask 会完成图片入库；.catch 兜底落库阶段可能抛出的未处理 rejection。
70:           void finalizeCompletedServerTask(currentJob, task, actions).catch(() => { /* 已落库 */ });
71:           return;
72:         }
73:         if (task.status === 'failed' || task.status === 'expired') {
74:           const { terminal } = classifyTaskFailure(task);
75:           const message = task.error || task.warning
76:             || (task.status === 'expired' ? '该任务已超出取回时间' : '后端任务失败');
77:           void actions.failJob(jobId, message, { terminal });
78:           return;
79:         }
80:         if (task.status === 'processing') {
81:           actions.replaceJob(jobId, current => ({ ...current, status: 'processing' }));
82:           return;
83:         }
84:         if (task.status === 'queued' || task.status === '排队中') {
85:           actions.replaceJob(jobId, current => ({ ...current, status: '排队中' }));
86:         }
87:       };
88:       const unsubscribe = novaTaskSocket.subscribeTask(taskId, handler);
89:       subscriptions.set(taskId, unsubscribe);
90:     }
91: 
92:     // 任务从等待状态消失（已完成/已删除）→ 取消订阅
93:     for (const [taskId, unsubscribe] of subscriptions) {
94:       if (!activeTaskIds.has(taskId)) {
95:         try { unsubscribe(); } catch { /* ignore */ }
96:         subscriptions.delete(taskId);
97:       }
98:     }
99:   }, [jobs]);
100: 
101:   return subscriptionsRef;
102: }

