14: function evictOldestIfNeeded() {
15:   if (blobFallbackStore.size <= MAX_FALLBACK_STORE_SIZE) return;
16:   // 找到最久未访问的条目并删除
17:   let oldestKey: string | null = null;
18:   let oldestTime = Infinity;
19:   for (const [key, entry] of blobFallbackStore) {
20:     if (entry.lastAccess < oldestTime) {
21:       oldestTime = entry.lastAccess;
22:       oldestKey = key;
23:     }
24:   }
25:   if (oldestKey !== null) {
26:     blobFallbackStore.delete(oldestKey);
27:   }
28: }
