50: export function parseStoredBlobRef(ref: string): { jobId: string; imageIndex: number } | null {
51:   if (!ref.startsWith('IDB:')) return null;
52: 
53:   const key = ref.substring(4);
54:   const separatorIndex = key.lastIndexOf('-');
55:   if (separatorIndex <= 0) return null;
56: 
57:   const imageIndex = Number(key.substring(separatorIndex + 1));
58:   if (!Number.isInteger(imageIndex) || imageIndex < 0) return null;
59: 
60:   return {
61:     jobId: key.substring(0, separatorIndex),
62:     imageIndex,
63:   };
