66: export type ImageDownloadStatus = 'pending' | 'downloading' | 'cached' | 'failed';
67: 
68: export interface ImageDownloadProgressItem {
69:   index: number;
70:   status: ImageDownloadStatus;
71:   loadedBytes: number;
72:   totalBytes?: number;
73:   percent?: number;
74:   error?: string;
