95: function parseContentLength(value: string | null): number | undefined {
96:   if (!value) return undefined;
97:   const parsed = Number(value);
98:   return Number.isFinite(parsed) && parsed > 0 ? parsed : undefined;
99: }
100: 
101: function getPercent(loadedBytes: number, totalBytes?: number): number | undefined {
102:   if (!totalBytes || totalBytes <= 0) return undefined;
103:   return Math.min(100, Math.max(0, Math.round((loadedBytes / totalBytes) * 100)));
104: }
