106: function createIdleTimeout(controller: AbortController): { reset: () => void; clear: () => void } {
107:   let timeout: ReturnType<typeof setTimeout> | undefined;
108:   const clear = () => {
109:     if (timeout) {
110:       clearTimeout(timeout);
111:       timeout = undefined;
112:     }
113:   };
114:   const reset = () => {
115:     clear();
116:     timeout = setTimeout(() => controller.abort(), IMAGE_DOWNLOAD_IDLE_TIMEOUT_MS);
117:   };
118:   return { reset, clear };
