121: async function readResponseAsBlob(
122:   response: Response,
123:   onProgress?: BlobDownloadProgressHandler,
124: ): Promise<Blob> {
125:   const totalBytes = parseContentLength(response.headers.get('content-length'));
126:   const contentType = response.headers.get('content-type') || 'image/png';
127: 
128:   if (!response.body) {
129:     const blob = await response.blob();
130:     onProgress?.({
131:       loadedBytes: blob.size,
132:       totalBytes: totalBytes || blob.size || undefined,
133:       percent: getPercent(blob.size, totalBytes || blob.size || undefined),
134:     });
135:     return blob;
136:   }
137: 
138:   const reader = response.body.getReader();
139:   const chunks: ArrayBuffer[] = [];
140:   let loadedBytes = 0;
141:   onProgress?.({ loadedBytes, totalBytes, percent: getPercent(loadedBytes, totalBytes) });
142: 
143:   for (;;) {
144:     const { done, value } = await reader.read();
145:     if (done) break;
146:     if (!value) continue;
147:     const chunk = new Uint8Array(value.byteLength);
148:     chunk.set(value);
149:     chunks.push(chunk.buffer);
150:     loadedBytes += value.byteLength;
151:     onProgress?.({ loadedBytes, totalBytes, percent: getPercent(loadedBytes, totalBytes) });
152:   }
153: 
154:   return new Blob(chunks, { type: contentType });
155: }
