157: export async function fetchImageAsBlob(
158:   url: string,
159:   maxRetries = 2,
160:   onProgress?: BlobDownloadProgressHandler,
161: ): Promise<Blob> {
162:   let lastError: Error | undefined;
163:   for (let attempt = 0; attempt < maxRetries; attempt++) {
164:     const controller = new AbortController();
