159:   private handleVisibilityChange = () => {
160:     if (document.visibilityState !== 'visible') return;
161:     if (this.taskHandlers.size === 0) return;
162:     // 页面回到前台：仅当连接既非 OPEN 也非 CONNECTING 时才重连。
163:     if (!this.hasLiveSocket()) {
164:       this.consecutiveFailures = 0;
165:       if (this.fallbackActive) this.stopFallback();
166:       this.scheduleReconnect(0);
