169: 
170:   private connect(): void {
171:     // 幂等：已有 OPEN/CONNECTING 连接时不再新建，避免重连路径（online/pageshow/
172:     // visibilitychange）在旧连接未关闭时泄漏出第二条连接。
173:     if (this.ws && (this.ws.readyState === WebSocket.OPEN || this.ws.readyState === WebSocket.CONNECTING)) {
174:       return;
175:     }
176:     if (!isWebSocketSupported()) {
177:       this.activateFallback();
178:       return;
179:     }
180:     const url = buildSocketUrl();
181:     if (!url) {
182:       this.activateFallback();
183:       return;
184:     }
185: 
186:     let ws: WebSocket;
187:     try {
188:       ws = new WebSocket(url);
189:     } catch {
190:       this.handleConnectFailure();
191:       return;
192:     }
193:     this.ws = ws;
194: 
195:     ws.addEventListener('open', () => {
196:       this.reconnectAttempt = 0;
197:       this.consecutiveFailures = 0;
198:       this.startHeartbeat();
199:       // 重新订阅
200:       const taskIds = Array.from(this.taskHandlers.keys());
201:       if (taskIds.length > 0) {
202:         this.send({ type: 'subscribeTasks', taskIds });
203:       }
204:       if (this.queueHandlers.size > 0) {
205:         this.send({ type: 'subscribeQueue' });
206:       }
207:     });
208: 
209:     ws.addEventListener('message', event => {
210:       let data: unknown;
211:       try {
212:         data = JSON.parse(typeof event.data === 'string' ? event.data : '');
213:       } catch {
214:         return;
215:       }
216:       this.handleServerMessage(data as ServerMessage);
217:     });
218: 
219:     ws.addEventListener('close', () => {
220:       this.stopHeartbeat();
221:       if (this.ws === ws) this.ws = null;
222:       this.handleConnectFailure();
223:     });
224: 
225:     ws.addEventListener('error', () => {
226:       // close 事件随后会触发，统一在那里处理
227:     });
228:   }
229: 
230:   private handleConnectFailure(): void {
231:     if (this.explicitlyDisabled) return;
232:     this.consecutiveFailures += 1;
233:     if (this.consecutiveFailures >= SOCKET_FAILURE_THRESHOLD) {
234:       this.activateFallback();
235:       return;
236:     }
237:     const delay = Math.min(
238:       RECONNECT_BASE_DELAY_MS * 2 ** this.reconnectAttempt,
239:       RECONNECT_MAX_DELAY_MS,
240:     );
241:     const jitter = Math.random() * 0.3 * delay;
242:     this.reconnectAttempt += 1;
243:     this.scheduleReconnect(delay + jitter);
244:   }
245: 
246:   private scheduleReconnect(delay: number): void {
247:     if (this.reconnectTimer) {
248:       clearTimeout(this.reconnectTimer);
249:       this.reconnectTimer = null;
250:     }
251:     if (this.explicitlyDisabled) return;
252:     this.reconnectTimer = setTimeout(() => {
253:       this.reconnectTimer = null;
254:       this.connect();
255:     }, delay);
256:   }
257: 
258:   private cleanupConnection(): void {
259:     if (this.reconnectTimer) {
260:       clearTimeout(this.reconnectTimer);
261:       this.reconnectTimer = null;
262:     }
263:     this.stopHeartbeat();
264:     if (this.ws) {
265:       try { this.ws.close(); } catch { /* ignore */ }
266:       this.ws = null;
267:     }
268:   }
269: 
270:   private startHeartbeat(): void {
271:     this.stopHeartbeat();
272:     this.heartbeatTimer = setInterval(() => {
273:       if (!this.ws || this.ws.readyState !== WebSocket.OPEN) return;
274:       this.send({ type: 'ping' });
275:       if (this.pongTimer) clearTimeout(this.pongTimer);
276:       this.pongTimer = setTimeout(() => {
277:         this.pongTimer = null;
278:         if (this.ws) {
279:           try { this.ws.close(); } catch { /* ignore */ }
280:         }
281:       }, HEARTBEAT_TIMEOUT_MS);
282:     }, HEARTBEAT_INTERVAL_MS);
283:   }
284: 
285:   private stopHeartbeat(): void {
286:     if (this.heartbeatTimer) {
287:       clearInterval(this.heartbeatTimer);
288:       this.heartbeatTimer = null;
289:     }
290:     if (this.pongTimer) {
291:       clearTimeout(this.pongTimer);
292:       this.pongTimer = null;
293:     }
294:   }
295: 
296:   private send(payload: unknown): void {
297:     if (!this.ws || this.ws.readyState !== WebSocket.OPEN) return;
298:     try {
299:       this.ws.send(JSON.stringify(payload));
300:     } catch {
301:       // send failure — connection will be cleaned up on close event
302:     }
303:   }
304: 
305:   private handleServerMessage(message: ServerMessage | null): void {
306:     if (!message || typeof message.type !== 'string') return;
307:     if (message.type === 'pong') {
308:       if (this.pongTimer) {
309:         clearTimeout(this.pongTimer);
310:         this.pongTimer = null;
311:       }
312:       return;
313:     }
314:     if (message.type === 'task') {
315:       const task = message.task;
316:       if (!task || typeof task.id !== 'string') return;
317:       const handlers = this.taskHandlers.get(task.id);
318:       if (!handlers) return;
319:       for (const handler of handlers) {
320:         try { handler(task); } catch { /* ignore handler error */ }
321:       }
322:       return;
323:     }
324:     if (message.type === 'queueStatus') {
325:       const stats = message.stats;
326:       if (!stats) return;
327:       for (const handler of this.queueHandlers) {
328:         try { handler(stats); } catch { /* ignore handler error */ }
329:       }
330:       return;
331:     }
332:     if (message.type === 'error') {
333:       // server error message received
334:     }
335:   }
