339:     if (this.fallbackActive) return;
340:     this.fallbackActive = true;
341:     this.cleanupConnection();
342:     this.runFallbackTick();
343:     this.fallbackTimer = setInterval(() => this.runFallbackTick(), HTTP_FALLBACK_INTERVAL_MS);
344:     // 兜底期间也允许通过 online/pageshow 重新尝试 socket
345:   }
346: 
