348:     if (!this.fallbackActive) return;
349:     this.fallbackActive = false;
350:     if (this.fallbackTimer) {
351:       clearInterval(this.fallbackTimer);
352:       this.fallbackTimer = null;
353:     }
354:   }
355: 
356:   private runFallbackTick(): void {
357:     if (this.fallbackInFlight) return;
358:     this.fallbackInFlight = true;
359:     const taskIds = Array.from(this.taskHandlers.keys());
360:     const promises: Promise<unknown>[] = [];
361:     for (const id of taskIds) promises.push(this.fetchTaskOnce(id));
362:     if (this.queueHandlers.size > 0) promises.push(this.fetchQueueOnce());
363:     Promise.allSettled(promises).finally(() => {
364:       this.fallbackInFlight = false;
365:     });
366:   }
367: 
368:   private async fetchTaskOnce(taskId: string): Promise<void> {
369:     try {
370:       const task = await getNovaTask(taskId);
371:       const handlers = this.taskHandlers.get(taskId);
372:       if (!handlers) return;
373:       for (const handler of handlers) {
374:         try { handler(task); } catch { /* ignore handler error */ }
375:       }
376:     } catch {
377:       // fallback fetch failure — will retry on next tick
378:     }
379:   }

