114:       const next = new Set(prev);
115:       next.add(url);
116:       return next;
117:     });
118:   }, []);
119: 
120:   const baseFilteredPrompts = useMemo(() => {
121:     let prompts = allPrompts;
122: 
123:     if (blacklist.length > 0) {
124:       prompts = prompts.filter((prompt) => {
125:         const contentToCheck = [
126:           prompt.title.toLowerCase(),
127:           prompt.content.toLowerCase(),
128:           prompt.contributor?.toLowerCase() || '',
129:           prompt.notes?.toLowerCase() || '',
130:           ...prompt.tags.map((tag) => tag.toLowerCase()),
131:         ].join(' ');
132: 
133:         return !blacklist.some((keyword) => contentToCheck.includes(keyword));
134:       });
135:     }
136: 
137:     const hasChinese = (text: string) => /[\u4e00-\u9fa5]/.test(text);
138:     prompts = prompts.filter((prompt) => hasChinese(prompt.title) || hasChinese(prompt.content));
139: 
140:     if (selectedCategory !== ALL_CATEGORY) {
141:       prompts = prompts.filter((prompt) => prompt.category === selectedCategory);
142:     }
