148:         || prompt.content.toLowerCase().includes(query)
149:         || (prompt.contributor && prompt.contributor.toLowerCase().includes(query))
150:       ));
151:     }
152: 
153:     return prompts;
154:   }, [allPrompts, blacklist, searchQuery, selectedCategory]);
155: 
156:   const filteredPrompts = useMemo(() => {
157:     const seed = `${searchQuery}\0${blacklist.join('\0')}\0${baseFilteredPrompts.map((prompt) => prompt.uniqueKey).join('\0')}`;
158:     return seededShuffle(baseFilteredPrompts, seed);
159:   }, [baseFilteredPrompts, blacklist, searchQuery]);
160: 
161:   useEffect(() => {
