163:   }, [pageStep, searchQuery, selectedCategory]);
164: 
165:   useEffect(() => {
166:     if (!loadMoreRef.current) return;
167: 
168:     const observer = new IntersectionObserver(
169:       (entries) => {
170:         if (entries[0].isIntersecting && displayCount < filteredPrompts.length) {
171:           setDisplayCount((prev) => Math.min(prev + pageStep, filteredPrompts.length));
172:         }
173:       },
174:       { rootMargin: '400px' },
175:     );
176: 
177:     observer.observe(loadMoreRef.current);
178:     return () => observer.disconnect();
179:   }, [displayCount, filteredPrompts.length, pageStep]);
180: 
181:   useEffect(() => {
