183:       setShowScrollTop(window.scrollY > 500);
184:     };
185:     window.addEventListener('scroll', handleScroll, { passive: true });
186:     return () => window.removeEventListener('scroll', handleScroll);
187:   }, []);
188: 
189:   useEffect(() => {
