204:     };
205:   }, [loading, onRestorePositionHandled, restorePosition]);
206: 
207:   const displayedPrompts = useMemo(() => filteredPrompts.slice(0, displayCount), [displayCount, filteredPrompts]);
208:   const hasMore = displayCount < filteredPrompts.length;
209: 
