221:         <AlertCircle className="w-12 h-12 text-destructive" />
222:         <p className="text-destructive">{error}</p>
223:       </div>
224:     );
225:   }
226: 
227:   return (
228:     <>
229:       <div ref={galleryRef} className="space-y-6">
230:         <div className="space-y-3">
231:           <div className="relative">
232:             <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
233:             <Input
234:               placeholder="搜索提示词、标题或作者..."
235:               value={searchQuery}
236:               onChange={(event) => setSearchQuery(event.target.value)}
237:               className="pl-9"
238:             />
239:           </div>
