1: "use client";
2: 
3: import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4: import { Download, FolderOpen, Frame, Layers, PanelLeftOpen, Plus, Trash2, Upload } from "lucide-react";
5: 
6: import { Button } from "@/components/ui/button";
7: import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
8: import { Input } from "@/components/ui/input";
9: import { Select } from "@/components/ui/select";
10: import { cn } from "@/lib/utils";
11: import type { PromptWithKey } from "@/lib/prompt-gallery-data";
12: import { CanvasEditor } from "./CanvasEditor";
13: import { buildTaskImportProject, type CanvasTaskImportRequest } from "./canvas-job-import";
14: import { CanvasThumbnail } from "./components/canvas-thumbnail";
15: import { useCanvasStore } from "./stores/use-canvas-store";
16: import { exportCanvasProjects, importCanvasProjectsFromZip } from "./utils/canvas-export";
17: 
18: type CanvasWorkspaceProps = {
19:   wideMode?: boolean;
20:   onConfigureApiKey: () => void;
21:   onEnableWideMode: () => void;
22:   showToast: (message: string, type: "success" | "error" | "info") => void;
23:   showPromptGallery?: boolean;
24:   taskImport?: CanvasTaskImportRequest | null;
25:   onTaskImportHandled?: () => void;
26:   promptGalleryImport?: PromptWithKey | null;
27:   onPromptGalleryImportHandled?: () => void;
28:   returnToPromptGallery?: boolean;
29:   onReturnToPromptGallery?: () => void;
30: };
31: 
32: type SortMode = "updated" | "created" | "name";
33: 
34: const SORT_OPTIONS: { value: SortMode; label: string }[] = [
35:   { value: "updated", label: "最近修改" },
36:   { value: "created", label: "创建时间" },
37:   { value: "name", label: "名称" },
38: ];
39: 
40: export function CanvasWorkspace({ wideMode, onConfigureApiKey, onEnableWideMode, showToast, showPromptGallery, taskImport, onTaskImportHandled, promptGalleryImport, onPromptGalleryImportHandled, returnToPromptGallery, onReturnToPromptGallery }: CanvasWorkspaceProps) {
41:   const hydrated = useCanvasStore((state) => state.hydrated);
42:   const projects = useCanvasStore((state) => state.projects);
43:   const createProject = useCanvasStore((state) => state.createProject);
44:   const renameProject = useCanvasStore((state) => state.renameProject);
45:   const deleteProjects = useCanvasStore((state) => state.deleteProjects);
46:   const importProject = useCanvasStore((state) => state.importProject);
47:   const updateProject = useCanvasStore((state) => state.updateProject);
48:   const handledTaskImportRef = useRef<CanvasTaskImportRequest | null>(null);
49:   const handledPromptGalleryImportRef = useRef<PromptWithKey | null>(null);
50: 
51:   const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
52:   const [editingId, setEditingId] = useState<string | null>(null);
53:   const [editingTitle, setEditingTitle] = useState("");
54:   const [deleteId, setDeleteId] = useState<string | null>(null);
55:   const [sortMode, setSortMode] = useState<SortMode>("updated");
56:   const [mounted, setMounted] = useState(false);
57:   const [taskImportTargetOpen, setTaskImportTargetOpen] = useState(false);
58:   const [taskImportTargetId, setTaskImportTargetId] = useState<string | null>(null);
59:   const importInputRef = useRef<HTMLInputElement>(null);
60: 
61:   useEffect(() => {
62:     const id = requestAnimationFrame(() => setMounted(true));
63:     return () => cancelAnimationFrame(id);
64:   }, []);
65: 
66:   const importTaskIntoCanvas = useCallback(async (request: CanvasTaskImportRequest, targetProjectId?: string | null) => {
67:     try {
68:       const imported = await buildTaskImportProject(request);
69:       if (targetProjectId) {
70:         const target = useCanvasStore.getState().projects.find((project) => project.id === targetProjectId);
71:         if (!target) throw new Error("目标画布不存在");
72:         const offsetX = Math.max(0, ...target.nodes.map((node) => node.position.x + node.width)) + 80;
73:         const nodes = (imported.nodes || []).map((node) => ({ ...node, position: { x: node.position.x + offsetX, y: node.position.y } }));
74:         updateProject(targetProjectId, {
75:           nodes: [...target.nodes, ...nodes],
76:           connections: [...target.connections, ...(imported.connections || [])],
77:         });
78:         setActiveProjectId(targetProjectId);
79:         showToast("任务已追加到现有画布", "success");
80:       } else {
81:         const projectId = importProject(imported);
82:         setActiveProjectId(projectId);
83:         showToast("任务已导入到新画布", "success");
84:       }
85:     } catch (error) {
86:       showToast(error instanceof Error ? error.message : "任务导入失败", "error");
87:     } finally {
88:       setTaskImportTargetOpen(false);
89:       onTaskImportHandled?.();
90:     }
91:   }, [importProject, onTaskImportHandled, showToast, updateProject]);
92: 
93:   useEffect(() => {
94:     if (!taskImport || !wideMode || !hydrated || handledTaskImportRef.current === taskImport) return;
95:     handledTaskImportRef.current = taskImport;
96:     setTaskImportTargetId(null);
97:     if (projects.length > 0) {
98:       setTaskImportTargetOpen(true);
99:       return;
100:     }
101:     void importTaskIntoCanvas(taskImport);
102:   }, [hydrated, importTaskIntoCanvas, projects.length, taskImport, wideMode]);
103: 
104:   useEffect(() => {
105:     if (!promptGalleryImport || !wideMode || !hydrated || handledPromptGalleryImportRef.current === promptGalleryImport) return;
106:     handledPromptGalleryImportRef.current = promptGalleryImport;
107:     const projectId = createProject(`提示词：${promptGalleryImport.title || "未命名"}`);
108:     setActiveProjectId(projectId);
109:   }, [createProject, hydrated, promptGalleryImport, wideMode]);
110: 
111:   useEffect(() => {
112:     if (!promptGalleryImport) handledPromptGalleryImportRef.current = null;
113:   }, [promptGalleryImport]);
114: 
115:   const handleReturnToPromptGallery = useCallback(() => {
116:     setActiveProjectId(null);
117:     onReturnToPromptGallery?.();
118:   }, [onReturnToPromptGallery]);
119: 
120:   const sortedProjects = useMemo(() => {
121:     const list = [...projects];
122:     if (sortMode === "name") list.sort((a, b) => a.title.localeCompare(b.title, "zh"));
123:     else if (sortMode === "created") list.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
124:     else list.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
125:     return list;
126:   }, [projects, sortMode]);
127: 
128:   // 画布仅在宽屏模式下可用（按宽度模式判断，非检测设备），以降低适配成本。
129:   if (!wideMode) {
130:     return (
131:       <div className="grid place-items-center rounded-2xl border border-dashed border-border py-20">
132:         <div className="flex max-w-sm flex-col items-center gap-3 px-6 text-center">
133:           <Frame className="size-10 text-muted-foreground" />
134:           <h2 className="text-base font-semibold">无限画布需要宽屏模式</h2>
135:           <p className="text-sm text-muted-foreground">请使用电脑，或切换到宽屏模式（窗口宽度需 ≥ 1280px）。</p>
136:           <Button size="sm" onClick={onEnableWideMode}>
137:             <PanelLeftOpen className="size-4" />
138:             切换宽屏模式
139:           </Button>
140:         </div>
141:       </div>
142:     );
143:   }
144: 
145:   if (activeProjectId) {
146:     return (
147:       <div className="relative h-full min-h-[70vh] w-full overflow-hidden rounded-2xl border border-border bg-card">
148:         <CanvasEditor
149:           projectId={activeProjectId}
150:           onBack={() => setActiveProjectId(null)}
151:           onRequireApiKey={onConfigureApiKey}
152:           showToast={showToast}
153:           showPromptGallery={showPromptGallery}
154:           promptGalleryImport={promptGalleryImport}
155:           onPromptGalleryImportHandled={onPromptGalleryImportHandled}
156:           returnToPromptGallery={returnToPromptGallery}
157:           onReturnToPromptGallery={handleReturnToPromptGallery}
158:         />
159:       </div>
160:     );
161:   }
162: 
163:   const closeTaskImportTarget = () => {
164:     setTaskImportTargetOpen(false);
165:     onTaskImportHandled?.();
166:   };
167: 
168:   const handleImport = async (file: File) => {
169:     try {
170:       const imported = await importCanvasProjectsFromZip(file);
171:       imported.forEach((project) => importProject(project));
172:       showToast(`已导入 ${imported.length} 个画布`, "success");
173:     } catch {
174:       showToast("导入失败，请确认是导出的画布 zip", "error");
175:     }
176:   };
177: 
178:   return (
179:     <div className="space-y-4">
180:       <div className="flex flex-wrap items-center justify-between gap-2">
181:         <div>
182:           <h2 className="text-lg font-semibold tracking-tight">无限画布</h2>
183:           <p className="text-xs text-muted-foreground">节点式画布生图 · 连线引用 · 生成走任务队列</p>
184:         </div>
185:         <div className="flex items-center gap-2">
186:           {projects.length > 0 && (
187:             <Select<SortMode> value={sortMode} onValueChange={setSortMode} options={SORT_OPTIONS} size="sm" contentClassName="min-w-32" />
188:           )}
189:           <input ref={importInputRef} type="file" accept=".zip" hidden onChange={(event) => { const file = event.target.files?.[0]; if (file) void handleImport(file); event.target.value = ""; }} />
190:           <Button variant="outline" size="sm" onClick={() => importInputRef.current?.click()}>
191:             <Upload className="size-4" />
192:             导入
193:           </Button>
194:           <Button size="sm" onClick={() => setActiveProjectId(createProject())}>
195:             <Plus className="size-4" />
196:             新建画布
197:           </Button>
198:         </div>
199:       </div>
200: 
201:       {!mounted || !hydrated ? (
202:         <div className="grid place-items-center rounded-2xl border border-dashed border-border py-16 text-sm text-muted-foreground">加载中…</div>
203:       ) : projects.length === 0 ? (
204:         <button
205:           type="button"
206:           onClick={() => setActiveProjectId(createProject())}
207:           className="flex w-full flex-col items-center justify-center gap-2 rounded-2xl border border-dashed border-border py-16 text-sm text-muted-foreground transition-colors hover:border-primary/50 hover:text-foreground"
208:         >
209:           <Layers className="size-8" />
210:           还没有画布，点击新建第一个
211:         </button>
212:       ) : (
213:         <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
214:           {sortedProjects.map((project) => (
215:             <div key={project.id} className={cn("group flex flex-col gap-2 rounded-2xl border border-border bg-card p-3 shadow-sm transition-colors hover:border-primary/40")}>
216:               <button type="button" className="block w-full" aria-label="打开画布" onClick={() => setActiveProjectId(project.id)}>
217:                 <CanvasThumbnail nodes={project.nodes} />
218:               </button>
219: 
220:               {editingId === project.id ? (
221:                 <form
222:                   onSubmit={(event) => {
223:                     event.preventDefault();
224:                     renameProject(project.id, editingTitle);
225:                     setEditingId(null);
226:                   }}
227:                 >
228:                   <Input autoFocus value={editingTitle} onChange={(event) => setEditingTitle(event.target.value)} onBlur={() => { renameProject(project.id, editingTitle); setEditingId(null); }} />
229:                 </form>
230:               ) : (
231:                 <button type="button" className="w-full rounded-md text-left transition-colors hover:text-primary" title="点击重命名" onClick={() => { setEditingId(project.id); setEditingTitle(project.title); }}>
232:                   <span className="line-clamp-1 font-medium">{project.title}</span>
233:                 </button>
234:               )}
235: 
236:               <p className="text-xs text-muted-foreground">
237:                 {project.nodes.length} 个节点 · {new Date(project.updatedAt).toLocaleString("zh-CN", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" })}
238:               </p>
239:               <div className="flex items-center gap-1">
240:                 <Button variant="secondary" size="sm" className="flex-1" onClick={() => setActiveProjectId(project.id)}>
241:                   <FolderOpen className="size-4" />
242:                   打开
243:                 </Button>
244:                 <Button variant="ghost" size="icon-sm" aria-label="导出" onClick={() => void exportCanvasProjects([project], project.title || "无限画布")}>
245:                   <Download className="size-4" />
246:                 </Button>
247:                 <Button variant="ghost" size="icon-sm" aria-label="删除" onClick={() => setDeleteId(project.id)}>
248:                   <Trash2 className="size-4" />
249:                 </Button>
250:               </div>
251:             </div>
252:           ))}
253:         </div>
254:       )}
255: 
256:       <Dialog open={Boolean(deleteId)} onOpenChange={(open) => !open && setDeleteId(null)}>
257:         <DialogContent className="sm:max-w-sm">
258:           <DialogHeader>
259:             <DialogTitle>删除画布</DialogTitle>
260:           </DialogHeader>
261:           <p className="text-sm text-muted-foreground">删除后无法恢复（图片也会从本地清理）。确定删除该画布吗？</p>
262:           <DialogFooter>
263:             <Button variant="outline" onClick={() => setDeleteId(null)}>
264:               取消
265:             </Button>
266:             <Button
267:               variant="destructive"
268:               onClick={() => {
269:                 if (deleteId) deleteProjects([deleteId]);
270:                 setDeleteId(null);
271:               }}
272:             >
273:               删除
274:             </Button>
