33: function openDB(): Promise<IDBDatabase | null> {
34:     if (typeof indexedDB === 'undefined') return Promise.resolve(null);
35: 
36:     return new Promise((resolve) => {
37:         const request = indexedDB.open(DB_NAME, DB_VERSION);
38: 
39:         request.onerror = () => resolve(null);
40:         request.onupgradeneeded = () => {
41:             const db = request.result;
42:             if (!db.objectStoreNames.contains(STORE_NAME)) {
43:                 db.createObjectStore(STORE_NAME, { keyPath: 'key' });
44:             }
45:         };
46:         request.onsuccess = () => resolve(request.result);
47:     });
48: }
