50: async function getCachedImage(key: string): Promise<CachedUploadImage | null> {
51:     const desktop = getDesktopBridge();
52:     if (desktop) {
53:         const record = await desktop.records.get<CachedUploadImage>('upload-cache', key);
54:         if (!record) return null;
55:         if (record.dataUrl) return record;
56:         const stored = await desktop.files.read('cache', `upload:${key}`);
57:         if (!stored) return null;
58:         return { ...record, dataUrl: await blobToDataUrl(storedFileToBlob(stored)) };
59:     }
60:     const db = await openDB();
61:     if (!db) return null;
62: 
63:     return new Promise((resolve) => {
64:         const tx = db.transaction(STORE_NAME, 'readonly');
65:         const req = tx.objectStore(STORE_NAME).get(key);
66:         req.onsuccess = () => resolve((req.result as CachedUploadImage) || null);
67:         req.onerror = () => resolve(null);
68:     });
69: }
