74:         const blob = dataUrlToBlob(record.dataUrl);
75:         if (!blob) throw new Error('上传缓存图片格式无效');
76:         await desktop.files.write('cache', `upload:${record.key}`, await blobToBytes(blob), blob.type || record.mimeType);
77:         await desktop.records.put('upload-cache', record.key, { ...record, dataUrl: '' });
78:         return;
