50: async function getCachedImage(key: string): Promise<CachedUploadImage | null> {
51:     const desktop = getDesktopBridge();
52:     if (desktop) {
53:         const record = await desktop.records.get<CachedUploadImage>('upload-cache', key);
54:         if (!record) return null;
55:         if (record.dataUrl) return record;
56:         const stored = await desktop.files.read('cache', `upload:${key}`);
57:         if (!stored) return null;
