32: export function formatElapsedTime(totalSeconds: number): string {
33:   const seconds = Math.max(0, Math.floor(totalSeconds));
34:   if (seconds < 60) return `${seconds}秒`;
35:   const minutes = Math.floor(seconds / 60);
36:   if (minutes < 60) return `${minutes}分${String(seconds % 60).padStart(2, '0')}秒`;
37:   return `${Math.floor(minutes / 60)}时${String(minutes % 60).padStart(2, '0')}分`;
38: }
