50: export function filterHistoryJobs(jobs: StoredJob[], searchValue: string): StoredJob[] {
51:   const normalizedSearch = normalizeSearchValue(searchValue);
52:   if (!normalizedSearch) return jobs;
53:   return jobs.filter(job => (
