59: export function groupJobsByDay(jobs: StoredJob[]): JobDayGroup[] {
60:   const today = new Date();
61:   const yesterday = new Date(today);
62:   yesterday.setDate(today.getDate() - 1);
63:   const getDayKey = (date: Date) => [date.getFullYear(), date.getMonth() + 1, date.getDate()]
64:     .map((part, index) => index === 0 ? String(part) : String(part).padStart(2, '0'))
65:     .join('-');
66:   const todayKey = getDayKey(today);
67:   const yesterdayKey = getDayKey(yesterday);
68:   const groups: JobDayGroup[] = [];
69: 
70:   jobs.forEach((job) => {
71:     const date = new Date(job.created_at);
72:     const validDate = !Number.isNaN(date.getTime());
73:     const key = validDate ? getDayKey(date) : 'unknown';
74:     const label = !validDate
75:       ? '较早记录'
76:       : key === todayKey
77:         ? '今天'
78:         : key === yesterdayKey
79:           ? '昨天'
80:           : new Intl.DateTimeFormat('zh-CN', { month: 'long', day: 'numeric', weekday: 'short' }).format(date);
81:     const currentGroup = groups.at(-1);
82:     if (!currentGroup || currentGroup.key !== key) groups.push({ key, label, jobs: [job] });
83:     else currentGroup.jobs.push(job);
84:   });
85: 
86:   return groups;
87: }
