368: function useColumnCount(
369:   ref: React.RefObject<HTMLDivElement | null>,
370:   wideMode: boolean,
371:   ready: boolean,
372: ) {
373:   const [columns, setColumns] = useState(() => (wideMode && ready ? 3 : 1));
374: 
375:   useEffect(() => {
376:     if (!wideMode || !ready) {
377:       queueMicrotask(() => setColumns(1));
378:       return;
379:     }
380:     const el = ref.current;
381:     if (!el) return;
382: 
383:     const compute = () => {
384:       const width = el.clientWidth;
385:       setColumns(getHistoryColumnCount(width));
386:     };
387: 
388:     compute();
389:     const observer = new ResizeObserver(compute);
390:     observer.observe(el);
391:     return () => observer.disconnect();
392:   }, [ref, wideMode, ready]);
393: 
394:   return wideMode ? columns : 1;
395: }
