515: export function HistoryJobList({
516:   active,
517:   wideMode = false,
518:   title,
519:   mode,
520:   historyFilter,
521:   emptyDescription,
522:   jobs,
523:   loadedImages,
524:   checkingJobIds,
525:   cooldowns,
526:   onRetry,
527:   onClear,
528:   onClearAll,
529:   onHistoryFilterChange,
530:   onCancel,
531:   onCheckStatus,
532:   onImportToCanvas,
533: }: HistoryJobListProps) {
534:   const hasActiveTimers = useMemo(() => active && jobs.some(job => isWaitingJob(job)), [active, jobs]);
535:   const now = useNow(hasActiveTimers);
536:   const clearScope: HistoryClearScope = historyFilter || (mode === 'image-to-image' ? 'image-to-image' : 'text-to-image');
537:   const [searchValue, setSearchValue] = useState('');
538:   const [selectedDayKey, setSelectedDayKey] = useState<string>();
539:   const [scrollToDayKey, setScrollToDayKey] = useState<string>();
540:   const normalizedSearch = normalizeSearchValue(searchValue);
541:   const filteredJobs = useMemo(() => filterHistoryJobs(jobs, normalizedSearch), [jobs, normalizedSearch]);
542:   const jobGroups = useMemo(() => groupJobsByDay(filteredJobs), [filteredJobs]);
543: 
544:   const handleSelectDay = useCallback((key: string) => {
545:     setSelectedDayKey(key);
546:     setScrollToDayKey(key);
547:   }, []);
548:   const handleVisibleDayChange = useCallback((key: string | undefined) => {
549:     if (key) setSelectedDayKey(key);
550:   }, []);
551:   const handleScrollToDayComplete = useCallback(() => {
552:     setScrollToDayKey(undefined);
553:   }, []);
554:   const effectiveScrollToDayKey = scrollToDayKey && jobGroups.some(group => group.key === scrollToDayKey)
555:     ? scrollToDayKey
556:     : undefined;
557: 
558:   const renderJobCard = (job: StoredJob) => {
559:     const hasImage = job.status === 'completed' && (job.images || job.imageData) && loadedImages.has(job.id);
560:     if (isWaitingJob(job)) {
561:       return <WaitingJobCard job={job} now={now} isChecking={checkingJobIds.has(job.id)} cooldownEnd={cooldowns.get(job.id)} onCancel={onCancel} onCheckStatus={onCheckStatus} />;
562:     }
563:     if (hasImage) {
564:       return <CompletedJobCard job={job} onClear={() => onClear(job.id)} onRetry={onRetry} onImportToCanvas={onImportToCanvas} />;
565:     }
566:     if (job.status === 'failed') {
567:       // terminal=true → 后端明确判定不可恢复，不显示"查看进度"
568:       // 其他情况（默认 / 网络错误 / 未分类）都允许"查看进度"，让用户兜底
569:       const allowCheckStatus = !job.terminal && !!job.serverTaskId;
570:       return (
571:         <div className="studio-failed-card h-full rounded-xl border border-destructive/20 bg-card p-3">
572:           <div className="flex items-start justify-between gap-3">
573:             <div className="flex min-w-0 gap-3">
574:               <div className="flex size-8 shrink-0 items-center justify-center rounded-md bg-destructive/10 text-destructive">
575:                 <AlertCircle className="size-4" />
576:               </div>
577:               <div className="min-w-0 space-y-1">
578:                 <p className="truncate text-sm text-foreground">&quot;{job.prompt}&quot;</p>
579:                 <p className="line-clamp-3 text-xs leading-5 text-destructive" title={job.error || '任务失败'}>{job.error || '任务失败'}</p>
580:                 <p className="truncate text-xs text-muted-foreground" title={getModelDisplayName(job.model)}>{getModelDisplayName(job.model)}</p>
581:               </div>
582:             </div>
583:             <div className="flex gap-1">
